package com.chatapp.server;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;

public class ChatServer {
    private static final int PORT = 8080;
    private static final int MAX_BODY_SIZE = 1 << 20; // 1 MB cap to prevent DoS
    private static final Map<String, UserSession> sessions = new ConcurrentHashMap<>();
    private static final Map<String, ChatRoom> rooms = new ConcurrentHashMap<>();
    private static final byte[] HMAC_KEY = loadHmacKey();

    private static byte[] loadHmacKey() {
        String key = System.getenv("PROXY_HMAC_KEY");
        if (key == null || key.isEmpty()) {
            throw new IllegalStateException("PROXY_HMAC_KEY environment variable must be set");
        }
        return key.getBytes(StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws Exception {
        ServerSocket server = new ServerSocket(PORT);
        System.out.println("Chat server listening on port " + PORT);
        while (true) {
            Socket client = server.accept();
            new Thread(() -> handleConnection(client)).start();
        }
    }

    static void handleConnection(Socket client) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(client.getInputStream()));
             PrintWriter out = new PrintWriter(client.getOutputStream(), true)) {

            String requestLine = in.readLine();
            Map<String, String> headers = parseHeaders(in);

            // Reverse proxy forwards authenticated user identity
            String proxyUserId = headers.get("x-authenticated-user");
            String proxySignature = headers.get("x-proxy-signature");
            String internalForward = headers.get("x-internal-forward");

            // Validate proxy signature to ensure request came from trusted proxy
            if (!validateProxySignature(proxyUserId, proxySignature, internalForward)) {
                sendResponse(out, 403, "{\"error\": \"Invalid proxy signature\"}");
                return;
            }

            // Parse the request path and method
            String[] parts = requestLine.split(" ");
            String method = parts[0];
            String path = parts[1];

            // Route handling
            if (path.startsWith("/api/rooms/") && path.endsWith("/messages") && method.equals("GET")) {
                handleGetMessages(out, path, headers, proxyUserId);
            } else if (path.startsWith("/api/rooms/") && path.endsWith("/messages") && method.equals("POST")) {
                String body = readBody(in, headers);
                handlePostMessage(out, path, headers, proxyUserId, body);
            } else if (path.equals("/api/rooms") && method.equals("POST")) {
                String body = readBody(in, headers);
                handleCreateRoom(out, proxyUserId, body);
            } else if (path.startsWith("/api/rooms/") && path.endsWith("/history") && method.equals("GET")) {
                handleGetHistory(out, path, headers, proxyUserId);
            } else {
                sendResponse(out, 404, "{\"error\": \"Not found\"}");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static boolean validateProxySignature(String userId, String signature, String internalForward) {
        if (userId == null || signature == null) return false;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(HMAC_KEY, "HmacSHA256");
            mac.init(keySpec);
            // Signature covers the userId and internal-forward header
            String payload = userId + "|" + (internalForward != null ? internalForward : "");
            byte[] computed = mac.doFinal(payload.getBytes("UTF-8"));
            String computedHex = bytesToHex(computed);
            return MessageDigest.isEqual(computedHex.getBytes(StandardCharsets.UTF_8), signature.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            return false;
        }
    }

    static void handleGetMessages(PrintWriter out, String path, Map<String, String> headers, String userId) {
        String roomId = extractRoomId(path);
        ChatRoom room = rooms.get(roomId);
        if (room == null) {
            sendResponse(out, 404, "{\"error\": \"Room not found\"}");
            return;
        }
        // Authorization: check room membership
        if (!room.isMember(userId)) {
            sendResponse(out, 403, "{\"error\": \"Not a member of this room\"}");
            return;
        }
        sendResponse(out, 200, room.getMessagesJson());
    }

    static void handleGetHistory(PrintWriter out, String path, Map<String, String> headers, String userId) {
        String roomId = extractRoomId(path);
        ChatRoom room = rooms.get(roomId);
        if (room == null) {
            sendResponse(out, 404, "{\"error\": \"Room not found\"}");
            return;
        }

        // The history endpoint always uses the authenticated user for authorization
        // Admin audit functionality is handled at the proxy layer, not here
        if (!room.isMember(userId)) {
            sendResponse(out, 403, "{\"error\": \"Not a member of this room\"}");
            return;
        }
        sendResponse(out, 200, room.getHistoryJson(userId));
    }

    static void handlePostMessage(PrintWriter out, String path, Map<String, String> headers, String userId, String body) {
        String roomId = extractRoomId(path);
        ChatRoom room = rooms.get(roomId);
        if (room == null) {
            sendResponse(out, 404, "{\"error\": \"Room not found\"}");
            return;
        }
        if (!room.isMember(userId)) {
            sendResponse(out, 403, "{\"error\": \"Not a member of this room\"}");
            return;
        }
        room.addMessage(userId, body);
        sendResponse(out, 201, "{\"status\": \"sent\"}");
    }

    static void handleCreateRoom(PrintWriter out, String userId, String body) {
        String roomId = UUID.randomUUID().toString().substring(0, 8);
        ChatRoom room = new ChatRoom(roomId, userId);
        rooms.put(roomId, room);
        sendResponse(out, 201, "{\"roomId\": \"" + jsonEscape(roomId) + "\"}");
    }

    static String extractRoomId(String path) {
        // /api/rooms/{roomId}/messages or /api/rooms/{roomId}/history
        String[] segments = path.split("/");
        return segments.length >= 4 ? segments[3] : "";
    }

    static Map<String, String> parseHeaders(BufferedReader in) throws IOException {
        Map<String, String> headers = new HashMap<>();
        String line;
        while ((line = in.readLine()) != null && !line.isEmpty()) {
            int colon = line.indexOf(':');
            if (colon > 0) {
                String key = line.substring(0, colon).trim().toLowerCase();
                String value = line.substring(colon + 1).trim();
                headers.put(key, value);
            }
        }
        return headers;
    }

    static String readBody(BufferedReader in, Map<String, String> headers) throws IOException {
        int contentLength;
        try {
            contentLength = Integer.parseInt(headers.getOrDefault("content-length", "0"));
        } catch (NumberFormatException e) {
            return "";
        }
        if (contentLength <= 0) {
            return "";
        }
        // Cap the body size to prevent unbounded memory allocation (DoS)
        if (contentLength > MAX_BODY_SIZE) {
            throw new IOException("Request body too large");
        }
        char[] buf = new char[contentLength];
        int total = 0;
        // Loop to handle partial reads so the full body is consumed
        while (total < contentLength) {
            int read = in.read(buf, total, contentLength - total);
            if (read == -1) break;
            total += read;
        }
        return new String(buf, 0, total);
    }

    static void sendResponse(PrintWriter out, int status, String body) {
        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);
        out.println("HTTP/1.1 " + status + " OK");
        out.println("Content-Type: application/json");
        out.println("Content-Length: " + bodyBytes.length);
        out.println();
        out.print(body);
        out.flush();
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    // Escape a string for safe inclusion in a JSON string literal
    static String jsonEscape(String s) {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder(s.length() + 16);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }
}

class UserSession {
    String userId;
    long createdAt;
    UserSession(String userId) { this.userId = userId; this.createdAt = System.currentTimeMillis(); }
}

class ChatRoom {
    String roomId;
    Set<String> members = ConcurrentHashMap.newKeySet();
    List<ChatMessage> messages = new CopyOnWriteArrayList<>();

    ChatRoom(String roomId, String creator) {
        this.roomId = roomId;
        this.members.add(creator);
    }

    boolean isMember(String userId) { return members.contains(userId); }
    void addMessage(String userId, String content) { messages.add(new ChatMessage(userId, content)); }

    String getMessagesJson() {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < messages.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append(messages.get(i).toJson());
        }
        sb.append("]");
        return sb.toString();
    }

    String getHistoryJson(String forUser) {
        StringBuilder sb = new StringBuilder("{\"user\": \"" + ChatServer.jsonEscape(forUser) + "\", \"messages\": [");
        for (int i = 0; i < messages.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append(messages.get(i).toJson());
        }
        sb.append("]}");
        return sb.toString();
    }
}

class ChatMessage {
    String sender;
    String content;
    long timestamp;

    ChatMessage(String sender, String content) {
        this.sender = sender;
        this.content = content;
        this.timestamp = System.currentTimeMillis();
    }

    String toJson() {
        return "{\"sender\": \"" + ChatServer.jsonEscape(sender) + "\", \"content\": \"" + ChatServer.jsonEscape(content) + "\", \"ts\": " + timestamp + "}";
    }
}
